/* details panel */
.dt{max-width:420px;padding:16px}
.dt-head{display:flex;align-items:center;gap:10px;margin-bottom:10px}
.dt-head .ms{color:var(--muted)}
.dt-head .t{font-size:15px;font-weight:600}
.dt-row{display:grid;grid-template-columns:130px 1fr;align-items:center;gap:10px;min-height:38px}
.dt-k{display:flex;align-items:center;gap:10px;font-size:13.5px;color:var(--text-dim)}
.dt-k .ms{color:var(--muted)}
.dt-v{display:flex;flex-wrap:wrap;align-items:center;gap:6px;min-width:0;padding:4px 6px;margin-left:-6px;font-size:13.5px;color:var(--text);cursor:text;transition:background-color .15s}
.dt-v:hover{background:var(--chip)}
.dt-v a{color:var(--accent);text-decoration:none;display:inline-flex;align-items:center;gap:5px}
.dt-v a .ms{font-size:13px}
.dt-v input{width:100%;background:transparent;border:0;outline:0;font:inherit;color:var(--text)}
.dt-v.edit{background:var(--chip);box-shadow:0 0 0 1px var(--accent)}
.dt-v .tag{display:inline-flex;align-items:center;gap:4px}
.dt-v .dz-av{width:20px;height:20px}
.dt-row.new{animation:enter .4s var(--ease) both}
.dt-add{display:inline-flex;align-items:center;gap:10px;margin-top:4px;padding:6px 0;font-size:13.5px;font-weight:500;color:var(--text)}
.dt-add .ms{color:var(--accent)}
.dt-foot{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:14px}
.dt-foot .btn{justify-content:center;gap:8px}
.dt-ext{margin-left:auto;color:var(--muted)}

/* details panel: remove a row, add one from a popup */
.dt{position:relative;overflow:visible!important}
.dt-row{grid-template-columns:130px 1fr 26px}
.dt-rm{width:24px;height:24px;display:grid;place-items:center;color:var(--muted);opacity:0;transition:opacity .15s,color .15s}
.dt-row:hover .dt-rm,.dt-rm:focus-visible{opacity:1}
.dt-rm:hover{color:var(--danger)}
.dt-pop{position:absolute;left:12px;right:12px;z-index:6;padding:14px;background:var(--panel);border:1px solid var(--icon-line);box-shadow:0 18px 44px -18px rgba(0,0,0,.4);opacity:0;visibility:hidden;transform:translateY(calc(-100% + 6px)) scale(.98);transform-origin:bottom left;transition:opacity .18s ease,transform .32s var(--ease),visibility 0s linear .32s}
.dt-pop.show{opacity:1;visibility:visible;transform:translateY(-100%);transition:opacity .18s ease,transform .32s var(--ease),visibility 0s}
.dt-pop-t{margin-bottom:10px;font-size:14px;font-weight:600}
.dt-f{display:flex;flex-direction:column;gap:5px;margin-bottom:10px;font-size:12px;font-weight:500;color:var(--text-dim)}
.dt-f input{height:36px;padding:0 10px;background:var(--panel);border:1px solid var(--icon-line);outline:0;font:inherit;font-size:13.5px;color:var(--text)}
.dt-f input:focus{border-color:var(--accent)}
.dt-types{display:flex;gap:6px}
.dt-types button{display:inline-flex;align-items:center;gap:6px;padding:6px 10px;border:1px solid var(--line);font-size:12.5px;font-weight:500;color:var(--text-dim);transition:border-color .2s,color .2s}
.dt-types button.on{border-color:var(--accent);color:var(--text)}
.dt-pop-a{display:flex;justify-content:flex-end;gap:8px;margin-top:4px}
[data-style="soft"] .dt-pop{border-radius:16px;border-color:var(--line)}
[data-style="soft"] .dt-f input{border-radius:10px;border-width:1.5px}
[data-style="soft"] .dt-types button{border-radius:999px;border-width:1.5px}
[data-style="soft"] .dt-rm{border-radius:7px}

/* details panel dropdowns */
.dt-v.is-menu{cursor:pointer}
.dt-car{margin-left:2px;font-size:13px;color:var(--muted)}
.stg{display:inline-flex;align-items:center;gap:6px;padding:2px 9px 2px 7px;border:1px solid var(--line);font-size:12.5px;font-weight:600;color:var(--text)}
.stg i{width:7px;height:7px;flex:none;background:var(--c)}
.stg-0{--c:#9a9aa6}.stg-1{--c:#3ecf8e}.stg-2{--c:#5d9bfb}.stg-3{--c:#a993ff}.stg-4{--c:#f59e0b}
[data-style="soft"] .stg{border:1.5px solid var(--cl);background:var(--cb);color:var(--text);border-radius:8px}
[data-style="soft"] .stg i{border-radius:50%;background:var(--ct)}
[data-style="soft"] .stg-0{--cb:var(--pg-bg);--cl:var(--pg-line);--ct:var(--pg-tx)}
[data-style="soft"] .stg-1{--cb:var(--pg-bg);--cl:var(--pg-line);--ct:var(--pm-tx)}
[data-style="soft"] .stg-2{--cb:var(--pg-bg);--cl:var(--pg-line);--ct:var(--pb-tx)}
[data-style="soft"] .stg-3{--cb:var(--pg-bg);--cl:var(--pg-line);--ct:var(--pl-tx)}
[data-style="soft"] .stg-4{--cb:var(--pg-bg);--cl:var(--pg-line);--ct:var(--pp-tx)}
.dt-menu{position:absolute;z-index:7;padding:4px;background:var(--panel);border:1px solid var(--icon-line);box-shadow:0 16px 36px -16px rgba(0,0,0,.35);opacity:0;visibility:hidden;transform:translateY(-4px) scale(.98);transform-origin:top left;transition:opacity .18s ease,transform .3s var(--ease),visibility 0s linear .3s}
.dt-menu.show{opacity:1;visibility:visible;transform:none;transition:opacity .18s ease,transform .3s var(--ease),visibility 0s}
.dt-mi{display:flex;align-items:center;gap:10px;width:100%;padding:7px 9px;text-align:left;font-size:13.5px;color:var(--text);transition:background-color .15s}
.dt-mi:hover{background:var(--chip)}
.dt-mi .dz-av{width:22px;height:22px}
.dt-mi>.ms{margin-left:auto;color:var(--accent);opacity:0}
.dt-mi.sel>.ms{opacity:1}
[data-style="soft"] .dt-menu{border-radius:14px;border-color:var(--line)}
[data-style="soft"] .dt-mi{border-radius:9px}

/* ---------- details panel ---------- */
{
  const dt = $('#dt'), rows = $('#dt-rows');
  const STAGES = ['Pre-seed','Seed','Series A','Series B','Series C+'];
  const PEOPLE = ['Maya Chen','Oscar Lind','Priya Nair','Joanna Kim','Jonas Weber','Ines Duarte'];
  let props = [
    ['dashboard','Name','text','Northwind Labs'],
    ['link','Website','link','northwind.co'],
    ['tag','Industry','tags',['Fintech','B2B']],
    ['group','Team size','select','51 to 200',['1 to 10','11 to 50','51 to 200','201 to 500','500+']],
    ['trending_up','Stage','stage','Series A'],
    ['home','Location','text','London, UK'],
    ['person','Owner','owner','Maya Chen']
  ];
  const stg = v => `<span class="stg stg-${STAGES.indexOf(v)}"><i></i>${v}</span>`;
  const caret = ic('expand_more','sm dt-car');
  const val = p => p[2] === 'link' ? `<a href="#" onclick="return false">${esc(p[3])}${ic('open_in_new','sm')}</a>`
    : p[2] === 'tags' ? p[3].map(t => `<span class="tag">${esc(t)}</span>`).join('')
    : p[2] === 'owner' ? `${avatar(p[3])}${p[3]}${caret}`
    : p[2] === 'stage' ? stg(p[3]) + caret
    : p[2] === 'select' ? esc(p[3]) + caret : esc(p[3]);
  const isMenu = p => ['select','stage','owner'].includes(p[2]);
  function render(fresh){
    rows.innerHTML = props.map((p, i) => `<div class="dt-row ${fresh === i ? 'new' : ''}"><span class="dt-k">${ic(p[0],'sm')}${esc(p[1])}</span><span class="dt-v ${isMenu(p) ? 'is-menu' : ''}" data-i="${i}" tabindex="0" ${isMenu(p) ? 'role="button" aria-haspopup="listbox"' : ''}>${val(p)}</span>${i ? `<button class="dt-rm" data-i="${i}" aria-label="Remove ${esc(p[1])}">${ic('close','sm')}</button>` : ''}</div>`).join('');
  }
  function edit(el){
    const i = +el.dataset.i, p = props[i]; if (el.classList.contains('edit')) return;
    const cur = Array.isArray(p[3]) ? p[3].join(', ') : p[3];
    el.classList.add('edit'); el.innerHTML = `<input value="${esc(cur)}">`; const inp = el.querySelector('input'); inp.focus(); inp.select();
    const done = save => { if (save){ const v = inp.value.trim(); if (v) p[3] = p[2] === 'tags' ? v.split(',').map(x => x.trim()).filter(Boolean) : v; Sound.play('select'); } render(); };
    inp.addEventListener('keydown', e => { if (e.key === 'Enter'){ e.preventDefault(); done(true); } else if (e.key === 'Escape') done(false); });
    inp.addEventListener('blur', () => done(true));
  }
  // dropdowns for team size, stage and owner
  const menu = document.createElement('div'); menu.className = 'dt-menu'; menu.setAttribute('role', 'listbox'); dt.appendChild(menu);
  let mi = null;
  function openMenu(el){
    mi = +el.dataset.i; const p = props[mi];
    const opts = p[2] === 'stage' ? STAGES : p[2] === 'owner' ? PEOPLE : p[4];
    menu.innerHTML = opts.map(o => `<button class="dt-mi ${o === p[3] ? 'sel' : ''}" data-v="${o}" role="option">${p[2] === 'stage' ? stg(o) : p[2] === 'owner' ? `${avatar(o)}<span>${o}</span>` : `<span>${o}</span>`}${ic('check','sm')}</button>`).join('');
    const dr = dt.getBoundingClientRect(), r = el.getBoundingClientRect();
    menu.style.left = (r.left - dr.left) + 'px'; menu.style.top = (r.bottom - dr.top + 4) + 'px'; menu.style.minWidth = Math.max(200, r.width) + 'px';
    menu.classList.add('show'); Sound.play('open');
  }
  const closeMenu = () => { menu.classList.remove('show'); mi = null; };
  menu.addEventListener('click', e => { const b = e.target.closest('.dt-mi'); if (!b) return; props[mi][3] = b.dataset.v; closeMenu(); render(); Sound.play('select'); });
  rows.addEventListener('click', e => {
    const rm = e.target.closest('.dt-rm');
    if (rm){ const i = +rm.dataset.i, gone = props[i]; const row = rm.closest('.dt-row'); row.style.transition = 'opacity .2s'; row.style.opacity = '0'; Sound.play('close'); setTimeout(() => { props.splice(i, 1); morph(dt, () => render()); }, 200); showToast(gone[1] + ' removed'); return; }
    const v = e.target.closest('.dt-v'); if (!v || e.target.closest('a')) return;
    if (v.classList.contains('is-menu')){ e.stopPropagation(); mi === +v.dataset.i ? closeMenu() : openMenu(v); } else edit(v);
  });
  rows.addEventListener('keydown', e => { const v = e.target.closest('.dt-v'); if (v && e.key === 'Enter' && !v.classList.contains('edit')){ e.preventDefault(); v.classList.contains('is-menu') ? openMenu(v) : edit(v); } });
  document.addEventListener('pointerdown', e => { if (mi !== null && !menu.contains(e.target) && !e.target.closest('.dt-v.is-menu')) closeMenu(); });
  // add a property from a small popup
  const pop = document.createElement('div'); pop.className = 'dt-pop'; dt.appendChild(pop);
  let type = 'text';
  function openPop(){
    type = 'text';
    pop.innerHTML = `<div class="dt-pop-t">New property</div>
      <label class="dt-f"><span>Name</span><input id="dt-pn" placeholder="Founded" autocomplete="off"></label>
      <div class="dt-f"><span>Type</span><div class="dt-types">${[['text','Text','edit_note'],['link','Link','link'],['tags','Tags','tag']].map(t => `<button class="${t[0] === type ? 'on' : ''}" data-t="${t[0]}">${ic(t[2],'sm')}${t[1]}</button>`).join('')}</div></div>
      <label class="dt-f"><span>Value</span><input id="dt-pv" placeholder="2019" autocomplete="off"></label>
      <div class="dt-pop-a"><button class="btn" data-a="cancel">Cancel</button><button class="btn primary" data-a="add">Add property</button></div>`;
    const ar = $('#dt-add').getBoundingClientRect(), dr = dt.getBoundingClientRect();
    pop.style.top = (ar.top - dr.top - 8) + 'px'; pop.classList.add('show'); Sound.play('open');
    setTimeout(() => $('#dt-pn').focus(), 60);
  }
  const closePop = () => pop.classList.remove('show');
  pop.addEventListener('click', e => {
    const t = e.target.closest('[data-t]'); if (t){ type = t.dataset.t; $$('[data-t]', pop).forEach(b => b.classList.toggle('on', b === t)); $('#dt-pv').placeholder = type === 'link' ? 'example.com' : type === 'tags' ? 'Design, AI' : '2019'; Sound.play('tick'); return; }
    const a = e.target.closest('[data-a]'); if (!a) return;
    if (a.dataset.a === 'cancel'){ closePop(); Sound.play('close'); return; }
    const n = $('#dt-pn').value.trim(), v = $('#dt-pv').value.trim();
    if (!n || !v){ (n ? $('#dt-pv') : $('#dt-pn')).focus(); Sound.play('fail'); return; }
    props.push([type === 'link' ? 'link' : type === 'tags' ? 'tag' : 'edit_note', n, type, type === 'tags' ? v.split(',').map(x => x.trim()).filter(Boolean) : v]);
    closePop(); morph(dt, () => render(props.length - 1)); Sound.play('pop');
  });
  pop.addEventListener('keydown', e => { if (e.key === 'Enter' && e.target.matches('input')){ e.preventDefault(); $('[data-a="add"]', pop).click(); } if (e.key === 'Escape') closePop(); });
  $('#dt-add').addEventListener('click', () => pop.classList.contains('show') ? closePop() : openPop());
  document.addEventListener('pointerdown', e => { if (pop.classList.contains('show') && !pop.contains(e.target) && !e.target.closest('#dt-add')) closePop(); });
  $('#dt-crm').addEventListener('click', () => { Sound.play('tab'); showToast('Opening the CRM record'); });
  $('#dt-web').addEventListener('click', () => { Sound.play('tab'); showToast('Opening northwind.co'); });
  render();
}
